public sealed class BookingValidator : AbstractValidator<BookingRequest>
{
    public BookingValidator()
    {
        RuleFor(x => x.NumberOfSeats).InclusiveBetween(1, 20);
        RuleFor(x => x.Date).NotEmpty();
    }
}

var result = new BookingValidator().Validate(request);
if (!result.IsValid) return Results.ValidationProblem(ToDictionary(result.Errors));
